package com.juvinotech.blog.service;
import com.juvinotech.blog.domain.*;import com.juvinotech.blog.dto.ApiDtos.PostRequest;import com.juvinotech.blog.repository.*;import org.junit.jupiter.api.*;import org.mockito.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PostServiceTest {@Mock PostRepository posts;@Mock CategoryRepository categories;@Mock TagRepository tags;@Mock ProjectRepository projects;PostService service;@BeforeEach void setup(){MockitoAnnotations.openMocks(this);service=new PostService(posts,categories,tags,projects);}@Test void calculatesSlugReadingTimeAndPublication(){var c=new Category();c.setId(1L);c.setName("Backend");c.setSlug("backend");when(categories.findById(1L)).thenReturn(Optional.of(c));when(posts.save(any())).thenAnswer(i->{Post p=i.getArgument(0);p.setId(10L);return p;});var req=new PostRequest("Olá Spring Boot",null,"Resumo","palavra ".repeat(230),null,Post.Status.PUBLISHED,true,1L,List.of(),null);var result=service.create(req);assertThat(result.slug()).isEqualTo("ola-spring-boot");assertThat(result.readingTime()).isEqualTo(2);assertThat(result.publishedAt()).isNotNull();}@Test void makesDuplicateSlugUnique(){var c=new Category();c.setId(1L);when(categories.findById(1L)).thenReturn(Optional.of(c));when(posts.existsBySlug("artigo")).thenReturn(true);when(posts.save(any())).thenAnswer(i->i.getArgument(0));var req=new PostRequest("Artigo",null,"Resumo","Conteúdo",null,Post.Status.DRAFT,false,1L,List.of(),null);assertThat(service.create(req).slug()).isEqualTo("artigo-2");}}
